= Schlyter vs engine at 2026-09-10T00:00:00
= Sun:   Schlyter lon 167.321015898   engine lon 167.319451956   |diff| 0.0938364904704 arcmin
= Mars ra  Schlyter 110.713875401   engine 110.717796062   |diff| 0.235239652319 arcmin
= Mars dec Schlyter 22.749424543   engine 22.751229886   |diff| 0.108320577118 arcmin
*/

/* ============================================================================
moon-node-passages.epher -- when the Moon crosses the ecliptic's nodes

Finds the instants in one month when the Moon crosses the ecliptic -
the ascending node (ecliptic latitude beta changing from south to
north) and the descending node (north to south) - by watching the sign
of the Moon's geocentric ecliptic latitude, computed from the built-in
ra and decl (the solar-ephemeris crate, ELP-MPP02, JPL-validated;
guide 1.16) through the ch. 13 rotation of moon-ecliptic-position.epher
(mean obliquity of date). The scan is the engine-truth version of the
mean-element treatment of Meeus ch. 51 ("Passages of the Moon through
the Nodes"): there the node passages follow from the mean elements,
here the ephemeris itself is read.

The method: the ecliptic latitude is sampled every 2 days across the
month (the Moon crosses the ecliptic about every 13.6 days, so each
sign change has a bracket), each bracket is halved 8 times by sign
(bisection on beta), and the crossing inside the final ~10-minute
bracket is pinned by linear interpolation - the latitude runs almost
straight through a node, so the interpolation error is seconds.

Accuracy: engine-grade: the crossing times are good to well under a
minute, limited only by the ephemeris. Months usually carry two
crossings; a month can hold one (or, rarely, three) when a crossing
sits near an edge - the scan reports what it finds inside the month.

Knobs: `year` and `month` (below: June 2026 - the Moon crosses the
ascending node on the 8th and the descending node on the 20th).
============================================================================ */

// ---- the knobs ----------------------------------------------------------------
const year = 2026
const month = 6

// ---- the scan geometry ----------------------------------------------------------
const j0 = jd(year, month, 1)         // 1st of the month, 0h UT
const d0 = j0 - 2                     // samples start two days early
const num = 18                          // samples, one every 2 days (17 brackets)

// ---- ecliptic latitude of the Moon (mean obliquity; ch. 13 rotation) -------------
def w360(x) = x - 360 * floor(x / 360)
def T(j) = (j - 2451545) / 36525
def eps(j) = 23.4392911 - 46.8150 * T(j) / 3600 - 0.00059 * T(j) ^ 2 / 3600 + 0.001813 * T(j) ^ 3 / 3600
def betaAt(j) = deg(asin(sin(rad(decl(11, j))) * cos(rad(eps(j))) - cos(rad(decl(11, j))) * sin(rad(eps(j))) * sin(rad(ra(11, j)))))   // ecliptic latitude, deg

// ---- the sign scan and the bisection ----------------------------------------------
def bsign(q) = betaAt(d0 + 2 * q)                       // beta at sample q
def nxt(q) = if q >= num - 1 then -1 else if bsign(q) * bsign(q + 1) < 0 then q else nxt(q + 1)   // first sign-change bracket at/after q, or -1
def hai(q) = (d0 + 2 * q - j0) * 24                     // sample q as hours after j0
def bis(a, b, k) = if k == 0 then {a, b} else if betaAt(j0 + (a + b) / 2 / 24) * betaAt(j0 + a / 24) < 0 then bis(a, (a + b) / 2, k - 1) else bis((a + b) / 2, b, k - 1)   // halve the bracket k times, hours after j0

// ---- results ----------------------------------------------------------------------
const r1 = nxt(0)
const r2 = nxt(r1 + 1)
print("node crossings of", month, "/", year, ":")

// The first crossing: its bracket, the sign change's direction, and the
// refined instant from 8 bisection halvings plus linear interpolation.
const br1 = bis(hai(r1), hai(r1) + 48, 8)
const ba1 = betaAt(j0 + br1[1] / 24)
const bb1 = betaAt(j0 + br1[2] / 24)
const tc1 = br1[1] + (br1[2] - br1[1]) * ba1 / (ba1 - bb1)
if r1 < 0 then "no node crossing this month" else (if bsign(r1) < 0 then "ascending node (beta - to +): " else "descending node (beta + to -): ") + iso(j0 + tc1 / 24) + " UT"

// The second crossing (absent when the month holds only one).
const br2 = bis(hai(r2), hai(r2) + 48, 8)
const ba2 = betaAt(j0 + br2[1] / 24)
const bb2 = betaAt(j0 + br2[2] / 24)
const tc2 = br2[1] + (br2[2] - br2[1]) * ba2 / (ba2 - bb2)
if r2 < 0 then "no second crossing this month" else (if bsign(r2) < 0 then "ascending node (beta - to +): " else "descending node (beta + to -): ") + iso(j0 + tc2 / 24) + " UT"

/* Self-check: the Moon's ecliptic latitude at the refined instants
must read zero (it defines the node). The printed values are the
interpolation residuals, fractions of an arcsecond. */
print("self-check: beta at the first crossing:", betaAt(j0 + tc1 / 24), "deg")
print("self-check: beta at the second crossing:", betaAt(j0 + tc2 / 24), "deg")

/* ---- expected output ----
= node crossings of 6 / 2026 :
= ascending node (beta - to +): 2026-06-07T06:20:18 UT
= descending node (beta + to -): 2026-06-19T17:58:09 UT
= self-check: beta at the first crossing: -0.000000134772847926 deg
= self-check: beta at the second crossing: -0.000000165352073043 deg
*/

/* ============================================================================
moon-phase-angle.epher -- the Sun-Moon-Earth angle across one month

The phase angle of the Moon on the same five dates of one month as
moon-illumination.epher, from the built-in accessor phase (the
solar-ephemeris crate, JPL-validated; guide 1.16). The phase angle is
the angle Sun-Moon-Earth measured at the Moon: 0 deg at full moon (Sun
and Earth line up on the same side of the Moon), 180 deg at new moon.
The lit fraction is exactly (1 + cos(phase angle)) / 2, and illum is
that value rounded to four decimals while phase is rounded to two, so
rebuilding illum from phase agrees to about 1e-4, as the checks below
show. Because of the Moon's 5 deg orbital tilt the angle at full moon
stays a few degrees above zero.

Knobs: year, month, and the sample days of the month.
============================================================================ */

// ---- the knobs --------------------------------------------------------------
const year = 2026
const month = 6
const days = {1, 8, 15, 22, 29}

// ---- model ------------------------------------------------------------------
// The lit fraction from the phase angle, radians trig (guide 1.13).
def lit(ph) = (1 + cos(rad(ph))) / 2

/* ---- results ----------------------------------------------------------------
Phase angle in degrees on the sample days. Small near the full moon of
June 29 (day 29: 11.81 deg), large near the new moon of June 15
(day 15: 174.94 deg); near 90 deg at the quarters (days 8 and 22). */
for d in days do phase(11, jd(year, month, d))

// The illuminated fraction on the same days (the same list as
// moon-illumination.epher), for direct comparison with the angles above.
for d in days do illum(11, jd(year, month, d))

// Rebuild illum from the phase angle and compare: (1 + cos(phase)) / 2
// with the phase in degrees. The residuals sit near 1e-4: illum is the
// same quantity rounded to 4 decimals, phase to 2.
print("day 1  rebuilt:", lit(phase(11, jd(year, month, 1))), "vs", illum(11, jd(year, month, 1)))
print("day 8  rebuilt:", lit(phase(11, jd(year, month, 8))), "vs", illum(11, jd(year, month, 8)))
print("day 15 rebuilt:", lit(phase(11, jd(year, month, 15))), "vs", illum(11, jd(year, month, 15)))
print("day 22 rebuilt:", lit(phase(11, jd(year, month, 22))), "vs", illum(11, jd(year, month, 22)))
print("day 29 rebuilt:", lit(phase(11, jd(year, month, 29))), "vs", illum(11, jd(year, month, 29)))

/* ---- expected output ----
= {8.43, 84.88, 174.94, 88.84, 11.81}
= {0.9946, 0.5447, 0.0019, 0.5102, 0.9894}
= day 1  rebuilt: 0.994597854232 vs 0.9946
= day 8  rebuilt: 0.544620987683 vs 0.5447
= day 15 rebuilt: 0.00194855869838 vs 0.0019
= day 22 rebuilt: 0.510122218124 vs 0.5102
= day 29 rebuilt: 0.989415841279 vs 0.9894
*/

/* ============================================================================
brightest-planet.epher -- which planet is brightest, by a search loop

Finds the planet with the smallest apparent magnitude (the brightest)
on 2026-06-01, by scanning the body numbers 1-9 (Earth, 3, is the
observer and never a target) with a while loop (guide 1.30). A loop
body is one statement, so the search state - the index, the best
magnitude so far and the best body number - is packed into one list
and updated as a whole. The magnitudes are first printed in a list;
the loop result is then checked against the list minimum from the
built-in min. Magnitudes come from the accessor mag (the solar-
ephemeris crate, JPL-validated; guide 1.16).

Knob: the date tm.
============================================================================ */

// ---- the knob ---------------------------------------------------------------
const tm = jd(2026, 6, 1)     // 0h UT

// ---- helpers ----------------------------------------------------------------
// The eight target bodies, and a name for each body number.
const bodies = {1, 2, 4, 5, 6, 7, 8, 9}
def name(b) = if b == 1 then "Mercury" else if b == 2 then "Venus" else if b == 4 then "Mars" else if b == 5 then "Jupiter" else if b == 6 then "Saturn" else if b == 7 then "Uranus" else if b == 8 then "Neptune" else "Pluto"

// ---- results ----------------------------------------------------------------
// The unrolled magnitudes, one per body in the same order: the search
// below must agree with what the eye reads off this list.
const m = {mag(1, tm), mag(2, tm), mag(4, tm), mag(5, tm), mag(6, tm), mag(7, tm), mag(8, tm), mag(9, tm)}

/* Search: s = {next index, best magnitude so far, best body number}.
Each step compares one magnitude against the best so far and keeps
the smaller (magnitude grows as brightness falls, so the minimum
magnitude is the brightest planet). */
s = {1, m[1], bodies[1]}
while s[1] < len(bodies) do s = {s[1] + 1, if m[s[1] + 1] < s[2] then m[s[1] + 1] else s[2], if m[s[1] + 1] < s[2] then bodies[s[1] + 1] else s[3]}

// The verdict, and the two checks: the best magnitude equals min of the
// list, and the body name matches the magnitude list printed above.
print("brightest planet:", name(s[3]), "at mag", s[2])
print("best mag equals min(m):", s[2] == min(m))
print("best body index:", s[3])

/* ---- expected output ----
= {1, -0.55, 1}
= brightest planet: Venus at mag -3.98
= best mag equals min(m): true
= best body index: 2
*/

/* ============================================================================
conjunction-planet-moon.epher -- the Moon's closest approach to a planet

The closest approach of the Moon to a chosen planet in a chosen month
(the appulse): the geocentric great-circle separation between the two
bodies (Meeus, "Astronomical Algorithms" 2nd ed., ch. 17, eq. 17.1) as a
function of time, minimized over the month. A two-day scan over the
month's thirty days finds the coarsest minimum (the Moon covers the sky
in 27.3 days, so the separation curve has exactly one dip per month);
a recursive golden-section search then homes the dip to about a minute.

The positions come from the built-in ra/decl accessors (solar-ephemeris
crate, ELP-MPP02 Moon, JPL-Horizons-validated; guide 1.29). The
separation is geocentric, the same number every almanac prints for a
Moon-planet appulse; an observer's topocentric view shifts it by the
Moon's parallax (up to a degree).

Accuracy: ephemeris-grade (arcsecond positions); the golden-section
minimum is good to a few minutes of time and a few arcseconds of
separation. The default month holds a fine pass: the Moon slides 0.85
degrees south of Jupiter on 2026-11-01.

Knobs: the planet (body number), the year and the month to search.
============================================================================ */

// ---- the knobs ---------------------------------------------------------------
const planet = 5                // Jupiter
const year = 2026
const month = 11
const jd0 = jd(year, month, 1)  // start of the month

// ---- helpers -----------------------------------------------------------------
// Geocentric great-circle separation of Moon and planet (Meeus eq. 17.1).
def sep(j) = deg(acos(sin(rad(decl(11, j))) * sin(rad(decl(planet, j))) + cos(rad(decl(11, j))) * cos(rad(decl(planet, j))) * cos(rad(ra(11, j) - ra(planet, j)))))
// Scan the month on a two-day grid (16 samples after the 1st); returns
// the day of the month (0-based grid index) with the smallest separation.
def scan(k, bk, bv) = if k > 15 then bk else if sep(jd0 + k * 2) < bv then scan(k + 1, k, sep(jd0 + k * 2)) else scan(k + 1, bk, bv)
// Golden-section search for the minimum over [a, b]: state carries the
// two interior trial points and their separations, one new date per step.
def gs(s) = if s[2] - s[1] < 0.0008 then (s[1] + s[2]) / 2 else if s[5] < s[6] then gs({s[1], s[4], s[1] + 0.381966011 * (s[4] - s[1]), s[3], sep(s[1] + 0.381966011 * (s[4] - s[1])), s[5]}) else gs({s[3], s[2], s[4], s[2] - 0.381966011 * (s[2] - s[3]), s[6], sep(s[2] - 0.381966011 * (s[2] - s[3]))})

// The month's coarsest minimum sits within a day of one of the scan days,
// so the golden search starts one day either side of the best sample.
const d0 = scan(1, 0, sep(jd0))        // best two-day sample (day index)
const ta = jd0 + d0 * 2 - 1             // golden search over +-1 day of it
const tb = jd0 + d0 * 2 + 1
const tmin = gs({ta, tb, ta + 0.381966011 * (tb - ta), ta + 0.618033989 * (tb - ta), sep(ta + 0.381966011 * (tb - ta)), sep(ta + 0.618033989 * (tb - ta))})

// ---- results ------------------------------------------------------------------
print("Moon and planet", planet, "in month", month, "/", year)
print("closest approach:", iso(tmin), "UT")
print("minimum separation:", sep(tmin), "deg =", deg2dms(sep(tmin)))
print("separation 6 h before:", sep(tmin - 0.25), "deg;  6 h after:", sep(tmin + 0.25), "deg")
print("Moon illuminated:", illum(11, tmin), "; planet magnitude:", mag(planet, tmin))

