= 2100: dec 89° 32' 26" polar dist 27.5662953448 arcmin
= closest approach: 2102.4 at polar distance 27.554384622 arcmin
*/

/* ============================================================================
star-tonight.epher -- where tonight's named stars stand, and when they transit

Takes three bright stars by their J2000 catalogue coordinates,
precesses them to the date with the rigorous method of Meeus ch. 21
(the same recipe precession-j2000.epher carries), and reads tonight's
sky for each: altitude and azimuth at the chosen instant from the
hour angle H = LST - RA (the built-in lst, guide 1.29, gives local
sidereal time), and the meridian transit instant from the sidereal
rate 1.002737909. This is the closed-form core of the communities'
observing programs - ticalc.org's "Celestia" (which turns catalogue
coordinates into horizon coordinates) and hpcalc's EPHE.

Accuracy: the precession is IAU-1976 (PyEphem agrees to a few
arcseconds on these very stars); the alt/az arithmetic is exact.
Aberration (about 20 arcseconds) is the known omission - fine for
pointing a telescope by hand. Polaris doubles as the sanity anchor:
its altitude at any instant must sit within a degree of the
observer's latitude.

Knobs: the place, the instant, and the star list below.
============================================================================ */

// ---- the knobs ----------------------------------------------------------------
const lat = 51.4779            // Greenwich
const lon = 0
const tm = jd(2026, 6, 21, 22)  // 22:00 UT in the summer evening

// ---- J2000 catalogue positions (SIMBAD), degrees ------------------------------
const vega_ra = hms2deg(18, 36, 56.34)
const vega_dec = dms2deg(38, 47, 1.3)
const arc_ra = hms2deg(14, 15, 39.67)      // Arcturus
const arc_dec = dms2deg(19, 10, 56.7)
const pol_ra = hms2deg(2, 31, 49.09)       // Polaris
const pol_dec = dms2deg(89, 15, 50.8)

// ---- Meeus ch. 21: of-date right ascension and declination --------------------
def cent0(j) = (j - jd(2000, 1, 1, 12)) / 36525
def sig(tt, T) = ((2306.2181 + 1.39656 * T - 0.000139 * T ^ 2) * tt + (0.30188 - 0.000344 * T) * tt ^ 2 + 0.017988 * tt ^ 3) / 3600
def zeta(tt, T) = ((2306.2181 + 1.39656 * T - 0.000139 * T ^ 2) * tt + (1.09468 + 0.000066 * T) * tt ^ 2 + 0.018203 * tt ^ 3) / 3600
def phi(tt, T) = ((2004.3109 - 0.8533 * T - 0.000217 * T ^ 2) * tt - (0.42665 + 0.000217 * T) * tt ^ 2 - 0.041833 * tt ^ 3) / 3600
def mod360(x) = x - 360 * floor(x / 360)
def s(j) = sig((j - jd(2000, 1, 1, 12)) / 36525, cent0(j))
def z(j) = zeta((j - jd(2000, 1, 1, 12)) / 36525, cent0(j))
def pj(j) = phi((j - jd(2000, 1, 1, 12)) / 36525, cent0(j))
def ra_of(ra, dec, j) = mod360(deg(atan2(cos(rad(dec)) * sin(rad(ra + s(j))), cos(rad(pj(j))) * cos(rad(dec)) * cos(rad(ra + s(j))) - sin(rad(pj(j))) * sin(rad(dec)))) + z(j))
def dec_of(ra, dec, j) = deg(asin(sin(rad(pj(j))) * cos(rad(dec)) * cos(rad(ra + s(j))) + cos(rad(pj(j))) * sin(rad(dec))))

// ---- horizon coordinates from the hour angle H = LST - RA ---------------------
def hangle(ra, dec, j) = lst(j, lon) * 15 - ra_of(ra, dec, j)
def alt_of(ra, dec, j) = deg(asin(sin(rad(lat)) * sin(rad(dec_of(ra, dec, j))) + cos(rad(lat)) * cos(rad(dec_of(ra, dec, j))) * cos(rad(hangle(ra, dec, j)))))
def az_of(ra, dec, j) = deg(atan2(sin(rad(hangle(ra, dec, j))), cos(rad(hangle(ra, dec, j))) * sin(rad(lat)) - tan(rad(dec_of(ra, dec, j))) * cos(rad(lat)))) + 180

// ---- meridian transit: catch up the sidereal rate from now --------------------
def mod24(x) = x - 24 * floor(x / 24)
def trans(ra, dec, j) = j + mod24(ra_of(ra, dec, j) / 15 - lst(j, lon)) / 1.002737909 / 24

// ---- results ------------------------------------------------------------------
print("tonight at", iso(tm), "lat", lat, "lon", lon)
print("Vega: alt", alt_of(vega_ra, vega_dec, tm), "az", az_of(vega_ra, vega_dec, tm), "transits", iso(trans(vega_ra, vega_dec, tm)))
print("Arcturus: alt", alt_of(arc_ra, arc_dec, tm), "az", az_of(arc_ra, arc_dec, tm), "transits", iso(trans(arc_ra, arc_dec, tm)))
print("Polaris: alt", alt_of(pol_ra, pol_dec, tm), "az", az_of(pol_ra, pol_dec, tm))

/* Self-check: Polaris stands within a degree of the observer's
latitude (it circles the pole 0.7 degrees out), and Arcturus, the
bright star of the summer evening, must already be west of the
meridian at 22:00 UT in late June. */
print("Polaris altitude minus latitude:", alt_of(pol_ra, pol_dec, tm) - lat, "deg")

/* ---- expected output ----
= tonight at 2026-06-21T22:00:00 lat 51.4779 lon 0
= Vega: alt 59.9563012032 az 99.328540057 transits 2026-06-22T00:36:57
= Arcturus: alt 51.729810024 az 221.77736537 transits 2026-06-22T20:12:48
= Polaris: alt 50.8683000991 az 0.231291506985
= Polaris altitude minus latitude: -0.609599900889 deg
*/

/* ============================================================================
analemma-point.epher -- where the true Sun sits versus mean solar time

Computes the analemma's data for one place: at a fixed mean-clock
noon through the year, how far the true Sun runs fast or slow (the
equation of time, the horizontal axis of the figure 8) and how high
it climbs (its declination, the vertical axis). Both axes come from
the closed-form solar theory of Jean Meeus, "Astronomical
Algorithms" 2nd ed.: the equation of time as in ch. 28 (the same
recipe equation-of-time.epher carries) and the declination from the
apparent longitude and the obliquity (ch. 25). The pair of dates in
May and July is the figure-8's signature: nearly the same
declination, six minutes of time apart.

The community ancestor is the HP-48 program "Analemma" (hpcalc.org
1933), which drew this figure on a 48's screen.

Accuracy: about +/- 0.1 minute on the time axis; the declination is
the low-precision solar theory, good to about 0.01 degree, which the
built-in decl confirms at the solstice below.

Knobs: the sample dates below (2026).
============================================================================ */

// ---- the knobs ----------------------------------------------------------------
const d_feb = {2026, 2, 12}
const d_may = {2026, 5, 14}
const d_jun = {2026, 6, 21}
const d_jul = {2026, 7, 26}
const d_nov = {2026, 11, 3}

// ---- Meeus ch. 28: mean elements in T (Julian centuries from J2000, TD) -------
def mod360(x) = x - 360 * floor(x / 360)
def cent(j) = (j + delta_t(j) / 86400 - jd(2000, 1, 1, 12)) / 36525
def l0(t) = mod360(280.46061837 + 36000.77005360 * t + 0.000387933 * t ^ 2 - t ^ 3 / 38710000)
def m(t) = mod360(357.5291092 + 35999.0502909 * t - 0.0001536 * t ^ 2)
def omega(t) = mod360(125.04 - 1934.136 * t)
def eps(t) = 23.4392911 - 0.0130042 * t - 0.000000164 * t ^ 2 + 0.000000504 * t ^ 3
def cen(t) = (1.914602 - 0.004817 * t - 0.000014 * t ^ 2) * sin(rad(m(t))) + (0.019993 - 0.000101 * t) * sin(rad(2 * m(t))) + 0.000289 * sin(rad(3 * m(t)))
def applon(t) = l0(t) + cen(t) - 0.0057183 - 0.0047833 * sin(rad(omega(t)))
def psi(t) = (-17.20 * sin(rad(omega(t))) - 1.32 * sin(rad(2 * l0(t))) + 0.21 * sin(rad(2 * omega(t)))) / 3600
def signed360(x) = if x > 180 then x - 360 else x
def eot(j) = signed360(l0(cent(j)) - 0.0057183 - alpha(cent(j)) + psi(cent(j)) * cos(rad(eps(cent(j))))) * 4
def alpha(t) = deg(atan2(cos(rad(eps(t))) * sin(rad(applon(t))), cos(rad(applon(t)))))
def sun_dec(t) = deg(asin(sin(rad(eps(t))) * sin(rad(applon(t)))))

// ---- results: the analemma's two axes, sampled --------------------------------
print("analemma at mean noon: minutes fast (+) vs declination")
print("2026-02-12:", eot(jd(d_feb[1], d_feb[2], d_feb[3])), "min, dec", sun_dec(cent(jd(d_feb[1], d_feb[2], d_feb[3]))), "deg")
print("2026-05-14:", eot(jd(d_may[1], d_may[2], d_may[3])), "min, dec", sun_dec(cent(jd(d_may[1], d_may[2], d_may[3]))), "deg")
print("2026-06-21:", eot(jd(d_jun[1], d_jun[2], d_jun[3])), "min, dec", sun_dec(cent(jd(d_jun[1], d_jun[2], d_jun[3]))), "deg")
print("2026-07-26:", eot(jd(d_jul[1], d_jul[2], d_jul[3])), "min, dec", sun_dec(cent(jd(d_jul[1], d_jul[2], d_jul[3]))), "deg")
print("2026-11-03:", eot(jd(d_nov[1], d_nov[2], d_nov[3])), "min, dec", sun_dec(cent(jd(d_nov[1], d_nov[2], d_nov[3]))), "deg")

/* The figure-8 signature, read off the pair above: May 14 and
July 26 straddle the June solstice within a degree of the same
declination - the Sun climbs the same height twice - while the
equation of time swings from +3.6 to -6.6 minutes. That swing is
the loop's width; the two real loops of the 8 come from the two
such pairs in a year. */

/* Self-check: the built-in decl (guide 1.29) at the June solstice
against the script's closed-form value. */
print("solstice decl, script:", sun_dec(cent(jd(2026, 6, 21))), "vs built-in:", decl(10, jd(2026, 6, 21)))

/* ---- expected output ----
= analemma at mean noon: minutes fast (+) vs declination
= 2026-02-12: -14.1935995278 min, dec -13.7599607635 deg
= 2026-05-14: 3.64145106631 min, dec 18.5778458092 deg
= 2026-06-21: -1.71739350749 min, dec 23.4354199958 deg
= 2026-07-26: -6.56279707087 min, dec 19.4733502814 deg
= 2026-11-03: 16.4392227149 min, dec -14.9924590918 deg
= solstice decl, script: 23.4354199958 vs built-in: 23.437516214
*/

/* ============================================================================
easter-sunday.epher -- the date of Easter for several years

Computes Gregorian Easter for a list of years with the computus of
chapter 8 of Jean Meeus, "Astronomical Algorithms" (2nd ed.,
Willmann-Bell, 1998): a chain of integer divisions and remainders
(floor and mod) on the year, ending in the month (March or April)
and day. The algorithm is exact integer arithmetic, so the results
are exact for every Gregorian year from 1583 on. Easter always falls
between March 22 and April 25; 2038 (April 25) is the latest it can
be. The dates were checked against python's datetime (each one is a
Sunday), and the expected output records them.

Knob: the list of years below.
============================================================================ */

// ---- the knob ---------------------------------------------------------------
const years = {2000, 2024, 2025, 2026, 2027, 2038}

// ---- Meeus ch. 8, Gregorian computus: one def per table value ---------------
def ea(y) = mod(y, 19)
def eb(y) = floor(y / 100)
def ec(y) = mod(y, 100)
def ed(y) = floor(eb(y) / 4)
def ee(y) = mod(eb(y), 4)
def ef(y) = floor((eb(y) + 8) / 25)
def eg(y) = floor((eb(y) - ef(y) + 1) / 3)
def eh(y) = mod(19 * ea(y) + eb(y) - ed(y) - eg(y) + 15, 30)
def ei(y) = floor(ec(y) / 4)
def ek(y) = mod(ec(y), 4)
def el(y) = mod(32 + 2 * ee(y) + 2 * ei(y) - eh(y) - ek(y), 7)
def em(y) = floor((ea(y) + 11 * eh(y) + 22 * el(y)) / 451)
def emonth(y) = floor((eh(y) + el(y) - 7 * em(y) + 114) / 31)
def eday(y) = mod(eh(y) + el(y) - 7 * em(y) + 114, 31) + 1

// ---- display ----------------------------------------------------------------
def pad2(n) = if n < 10 then "0" + str(n) else str(n)
def iso_date(y, m, d) = str(y) + "-" + pad2(m) + "-" + pad2(d)

// ---- results ----------------------------------------------------------------
// Easter 2026 is April 5 (the anchor of this script); 2038 lands on
// April 25, the latest possible date, and 2024 on March 31.
print("Easter 2000:", iso_date(2000, emonth(2000), eday(2000)))
print("Easter 2024:", iso_date(2024, emonth(2024), eday(2024)))
print("Easter 2025:", iso_date(2025, emonth(2025), eday(2025)))
print("Easter 2026:", iso_date(2026, emonth(2026), eday(2026)))
print("Easter 2027:", iso_date(2027, emonth(2027), eday(2027)))
print("Easter 2038:", iso_date(2038, emonth(2038), eday(2038)))

// A check that needs no calendar table: every computed Easter must be
// a Sunday, i.e. weekday number 0 in the 0 = Sunday convention of
// day-of-week-from-date.epher. It prints true.
def sunday(y) = mod(floor(jd(y, emonth(y), eday(y)) + 1.5), 7) == 0
print("computed Easter 2026 is a Sunday:", sunday(2026))
print("computed Easter 2038 is a Sunday:", sunday(2038))

/* ---- expected output ----
= Easter 2000: 2000-04-23
= Easter 2024: 2024-03-31
= Easter 2025: 2025-04-20
= Easter 2026: 2026-04-05
= Easter 2027: 2027-03-28
= Easter 2038: 2038-04-25
= computed Easter 2026 is a Sunday: true
= computed Easter 2038 is a Sunday: true
*/

/* ============================================================================
hebrew-calendar.epher -- Gregorian date to the Hebrew calendar

Converts a Gregorian date into the Hebrew (Jewish) calendar: the
year, month name and day. The calendar is lunar-solar: months track
the Moon, and a 13th month (Adar I) is intercalated in the 7 leap
years of each 19-year cycle. The algorithm follows Meeus,
"Astronomical Algorithms" 2nd ed. ch. 9 and the standard molad
arithmetic: the mean lunation is 29d 12h 793p (parts of 1/1080
hour), and the postponement rules (Molad Zaken; the "Lo ADU" rule
that Rosh Hashanah never falls on Sunday, Wednesday or Friday; the
late-molad rules of leap and post-leap years) place 1 Tishri. The
weekday count starts from the epoch: 1 Tishri 1 fell on a Monday,
JD 347997.5.

Accuracy: this is the fixed arithmetic calendar, exact by
construction; the printed anchors match the reference converter
Hebcal for 1 Tishri of 5781-5787.

Knobs: the date below.
============================================================================ */

// ---- the knobs ---------------------------------------------------------------------
const yr = 2026
const m = 9
const dcal = 7

// ---- molad arithmetic (integer; weekday 0 = Monday) ----------------------------------
def leapv(yy) = mod(7 * yy + 1, 19) < 7
def mcnt(yy) = floor((235 * yy - 234) / 19)
def prt(yy) = mod(12084 + 13753 * mcnt(yy), 25920)
def bd(yy) = 29 * mcnt(yy) + floor((12084 + 13753 * mcnt(yy)) / 25920) + (if prt(yy) >= 19440 then 1 else 0)
def d2(yy) = bd(yy) + (if mod(bd(yy), 7) == 2 or mod(bd(yy), 7) == 4 or mod(bd(yy), 7) == 6 then 1 else 0)
def d3(yy) = d2(yy) + (if mod(d2(yy), 7) == 0 and prt(yy) >= 16789 and leapv(yy) then 1 else 0)
def tishri(yy) = d3(yy) + (if mod(d3(yy), 7) == 1 and prt(yy) >= 9924 and not leapv(yy) and leapv(yy - 1) then 2 else 0)
def L(yy) = tishri(yy + 1) - tishri(yy)
def hh(yy) = if mod(L(yy), 10) == 5 then 30 else 29
def kk(yy) = if mod(L(yy), 10) == 3 then 29 else 30

// ---- month lengths and names ------------------------------------------------------------
def lens(yy) = if leapv(yy) then {30, hh(yy), kk(yy), 29, 30, 30, 29, 30, 29, 30, 29, 30, 29} else {30, hh(yy), kk(yy), 29, 30, 29, 30, 29, 30, 29, 30, 29}
def mn(k, yy) = if k == 1 then "Tishri" else if k == 2 then "Heshvan" else if k == 3 then "Kislev" else if k == 4 then "Tevet" else if k == 5 then "Shevat" else if k == 6 then (if leapv(yy) then "Adar I" else "Adar") else if k == 7 then (if leapv(yy) then "Adar II" else "Nisan") else if k == 8 then "Iyar" else if k == 9 then "Sivan" else if k == 10 then "Tamuz" else if k == 11 then "Av" else "Elul"
def acc(k, yy) = if k == 1 then 0 else acc(k - 1, yy) + lens(yy)[k - 1]
def findm(k, yy, dy) = if dy < acc(k, yy) + lens(yy)[k] then k else findm(k + 1, yy, dy)

// ---- the conversion -----------------------------------------------------------------------
const jdn = floor(jd(yr, m, dcal) + 0.5)
def findy(yy, j) = if j >= tishri(yy) + 347998 then yy else findy(yy - 1, j)
const yh = findy(yr + 3762, jdn)
const dyv = jdn - tishri(yh) - 347998
const km = findm(1, yh, dyv)
const dm = dyv - acc(km, yh) + 1

print("Gregorian", yr, "-", m, "-", dcal, "is Hebrew", dm, mn(km, yh), yh)
print("1 Tishri", yh, "falls on JDN", tishri(yh) + 347998, "and the year has", L(yh), "days")

/* Self-check against the reference converter (Hebcal): 2024-03-10
reads 30 Adar I 5784 (day 176 of that leap year). */
print("2024-03-10 is 30 Adar I 5784:", floor(jd(2024, 3, 10) + 0.5) - tishri(5784) - 347998 == 176)

/* ---- expected output ----
= Gregorian 2026 - 9 - 7 is Hebrew 25 Elul 5786
= 1 Tishri 5786 falls on JDN 2460942 and the year has 354 days
= 2024-03-10 is 30 Adar I 5784: true
*/

/* ============================================================================
limit-of-rational-at-infinity.epher -- a ratio of quadratics tends to 3

(3n^2 + 2n - 1)/(n^2 + 5) -> 3 as n -> infinity: dividing top and
bottom by n^2 gives (3 + 2/n - 1/n^2)/(1 + 5/n^2), whose terms all
die except the 3 (Stewart, "Calculus", 8th ed., sec. 2.6, limits of
rational functions at infinity). The leading correction is 2/n, which
is why n = 1e4 gives 3.0002 and n = 1e9 gives 3.000000002.

At n = 10 and n = 100 the arithmetic is exact integer division, and
epher shows the repeating decimals as fractions: 319/105 and 1313/435
(3.038095... and 3.01999...). The display, not the math, differs.

Accuracy: exact rational values at small n; values at large n round
at about the 12th digit (2e-9 from the limit at n = 1e9).

The knobs to edit are `ns` and `big` below.
============================================================================ */

// ---- the knobs --------------------------------------------------------------
const ns = {10, 100, 10000, 1000000000}

// ---- the ratio at growing n, as a collected list ----------------------------
for n in ns do (3*n^2 + 2*n - 1)/(n^2 + 5)

// ---- the limit: the ratio of the leading coefficients, 3/1 ------------------
print("within 1e-6 of the limit:", abs((3*ns[4]^2 + 2*ns[4] - 1)/(ns[4]^2 + 5) - 3) < 1e-6)
print("the limit:", 3)

/* ---- expected output ---------------------------------------------------------
= {319/105, 1313/435, 3.00019983999, 3.000000002}
= within 1e-6 of the limit: true
= the limit: 3
*/

/* ============================================================================
limit-of-sinx-over-x.epher -- sin(xv)/xv at tiny xv rounds to 1

The classic squeeze-theorem limit sin(xv)/xv -> 1 as xv -> 0 (Stewart,
"Calculus", 8th ed., sec. 2.6) probed numerically at xv = 1e-8, both
signs. The ratio misses 1 by about xv^2/6 = 1.7e-17 there, far below
the calculator's precision, so it prints exactly 1; at xv = 1e-4 the
deficit xv^2/6 = 1.7e-9 shows up in the last printed digits instead.

The same limit defines the derivative of sin xv at 0, and the builtin
derivative (a numeric central difference, not symbolic) agrees.

Accuracy: in exact arithmetic sin(xv)/xv at xv = 1e-8 is 1 - 1.7e-25;
every value below rounds at about the 12th printed digit.

The knob to edit is `xv` below.
============================================================================ */

// ---- the knob ---------------------------------------------------------------
const xv = 1e-8

// ---- sin(xv)/xv at xv = 1e-8 and -1e-8: both print the limit, 1 ----------------
print("at +xv:", sin(xv)/xv)
print("at -xv:", sin(-xv)/(-xv))
print("within 1e-12 of the limit:", abs(sin(xv)/xv - 1) < 1e-12)

// ---- at xv = 1e-4 and 1e-6 the xv^2/6 deficit is (partly) visible -------------
for t in {1e-4, 1e-6} do sin(t)/t

// ---- cross-check: derivative of sin at 0, on a fresh variable t -----------
// (xv is bound by the knob above, so a bound xv would make the expression
// constant; t is free).
print("the same limit, as a derivative:", derivative(sin(t), 0))

/* ---- expected output ---------------------------------------------------------
= at +xv: 1
= at -xv: 1
= within 1e-12 of the limit: true
= {0.999999998333, 1}
= the same limit, as a derivative: 1
*/

/* ============================================================================
runge-kutta-4.epher -- the classic RK4 method for y' = y on [0, 1]

epher has no builtin ODE solver, so the method is the point. The
classic fourth-order Runge-Kutta method (Kutta, 1901; Burden and
Faires, "Numerical Analysis", ch. 5) estimates the slope of y' = y
as a weighted average of four trial slopes per step:

  k1 = f(t, y)
  k2 = f(t + h/2, y + h k1/2)
  k3 = f(t + h/2, y + h k2/2)
  k4 = f(t + h, y + h k3)
  y += h (k1 + 2 k2 + 2 k3 + k4)/6

For y' = y the slope f(t, y) = y never uses t, so the helpers below
take y alone; a def helper holds each slope and one def composes the
step. The packed while loop carries {t, y, step} and runs 10 steps of
h = 0.1 from y(0) = 1. The result at t = 1, 2.71827974414, misses e by
2.08e-6, about 60000 times closer than Euler's 0.12454 at the same
step size: RK4 is a fourth-order method, its error falls like h^4.

Accuracy: the printed value is exact at its 12 displayed digits; the
residual against e is 0.00000208432387927, checked at 1e-5.

The knobs to edit are `h` and `steps` below.
============================================================================ */

// ---- the knobs --------------------------------------------------------------
const h = 0.1                  // step size
const steps = 10               // steps to reach t = 1

// ---- helpers: the equation and the four RK4 slopes --------------------------
def slope(y) = y               // the equation: y' = y
// For y' = y the slopes never use t, so k-defs take y alone (general
// f(t, y) form shown in the header).
def k1(y, h) = slope(y)
def k2(y, h) = slope(y + h/2*k1(y, h))
def k3(y, h) = slope(y + h/2*k2(y, h))
def k4(y, h) = slope(y + h*k3(y, h))
def rk4step(y, h) = y + h/6*(k1(y, h) + 2*k2(y, h) + 2*k3(y, h) + k4(y, h))

// ---- one RK4 run from t = 0 to t = 1, state {t, y, step} --------------------
v = {0, 1, 0}
while v[3] < steps do v = {v[1] + h, rk4step(v[2], h), v[3] + 1}
print("the state after the run:", v)
print("y(1) by RK4 with h = 0.1:", v[2])
print("true value e:", e)
print("error:", e - v[2])
print("within 1e-5 of e:", abs(v[2] - e) < 1e-5)
print("Euler's error at the same h for contrast:", 0.124539368359)

/* ---- expected output ---------------------------------------------------------
= {0, 1, 0}
= the state after the run: {1, 2.71827974414, 10}
= y(1) by RK4 with h = 0.1: 2.71827974414
= true value e: 2.71828182846
= error: 0.00000208432387927
= within 1e-5 of e: true
= Euler's error at the same h for contrast: 0.124539368359
*/

/* ============================================================================
rule-of-72.epher -- the Rule of 72 estimate of doubling time versus the
exact doubling time, for rates from 6% to 10%

The Rule of 72 says money doubles in about 72/(100*r) years at annual
rate r, i.e. 72 divided by the rate in percent: 12 years at 6%. The exact
doubling time solves (1+r)^t = 2, so t = ln(2)/ln(1+r). This script prints
both side by side for every whole percent from 6 to 10. Source: standard
finance lore; the exact formula is Kellison, The Theory of Interest,
chapter 2. The rule stays within a few months of the truth across this
range.

Accuracy: the exact times are irrational and print to 12 digits; 72/7
prints as the fraction 72/7 because its decimal repeats (epher's exact
fraction display shows the same number as 10.2857142857...).

The rate range 6% to 10% is the rule's usual comfort zone.
============================================================================ */

// ---- helpers ----------------------------------------------------------------
def doubletime(r) = ln(2) / ln(1 + r)   // exact doubling time at rate r, years

// ---- results -----------------------------------------------------------------
// Table rows are: rate in percent, the rule's estimate 72/rate, and the
// exact doubling time ln(2)/ln(1 + rate/100).
for p in 6 to 10 do {p, 72 / p, doubletime(p / 100)}
// The classic example: at 6% the rule says 12 years, the exact answer is
// 11.8957, so the rule runs about 0.10 years (5 weeks) high.
print("rule of 72 at 6%:", 72 / 6, "years")
print("exact doubling time at 6%:", doubletime(6%))
/* ---- expected output ----
= {{6, 12, 11.8956610459}, {7, 72/7, 10.2447683511}, {8, 9, 9.006468342}, {9, 8, 8.04323172693}, {10, 7.2, 7.27254089734}}
= rule of 72 at 6%: 12 years
= exact doubling time at 6%: 11.8956610459
*/

/* ============================================================================
discounted-payback-period.epher -- how many years until a project's
DISCOUNTED cash flows recover its cost

The discounted payback works like the plain payback (the sibling script
payback-period.epher) but discounts every inflow back to today at the
cost of capital first: each year k contributes flow_k/(1+r)^k. Because
later money is worth less, the discounted cumulative total recovers more
slowly, and the payback lengthens. The recurrence is written out; the
builtin npv validates the final cumulative total (it is the project's
npv). Source: standard capital-budgeting practice; see Brealey and
Myers, Principles of Corporate Finance, chapter 5.

Accuracy: exact fractions where the decimal repeats, 12 displayed digits
otherwise. The discount rate r = 8% is the cost of capital.

The knobs to edit are in the knob section; everything after it is
machinery you can leave alone.
============================================================================ */

// ---- knobs ------------------------------------------------------------------
const invested = 100000     // the project's cost today
const rate = 8%             // the cost of capital (discount rate)
const yearly = {30000, 40000, 40000, 30000}   // inflows at the end of years 1 to 4

// ---- helpers ----------------------------------------------------------------
def dflow(k) = yearly[k] / (1 + rate) ^ k                                    // year k inflow, discounted to today
def dcum(k) = if k == 1 then dflow(1) - invested else dcum(k - 1) + dflow(k)  // discounted cumulative through year k

/* ---- results -----------------------------------------------------------------
Discounted cumulative cash flow through each year. Row 1, -650000/9, is
the exact fraction for -72222.22...; the display keeps fractions when the
decimal repeats (epher's exact display). Row 4 is the project's npv. */
for k in 1 to 4 do {k, dcum(k)}
print("npv (the row 4 total), builtin check:", npv(rate, {-100000, 30000, 40000, 40000, 30000}))
// Count the full years on the discounted totals: the loop state is {year,
// discounted cumulative} and runs until the total turns positive.
v = {0, 0 - invested}
while v[2] < 0 do v = {v[1] + 1, v[2] + dflow(v[1] + 1)}
// Payback = last full year plus the fraction of the next year that covers
// the shortfall.
print("discounted payback period:", (v[1] - 1) + (dflow(v[1]) - v[2]) / dflow(v[1]), "years")
/* The discounted payback of 3.28 years beats the plain payback of 2.75
because the 40000 inflows of years 3 and 4 are worth only 31753.29 and
22050.90 once discounted. Raise the discount rate far enough and the
project never pays back at all (its npv turns negative). */
/* ---- expected output ----
= {{1, -650000/9}, {2, -27650000/729}, {3, -6175.37976934}, {4, 15875.5158145}}
= npv (the row 4 total), builtin check: 15875.5158145
= {0, -100000}
= discounted payback period: 3.2800512 years
*/

/* ============================================================================
payback-period.epher -- how many years until a project's cash flows
recover its cost, ignoring the time value of money

The payback period adds up the yearly inflows until the cumulative total
reaches the initial outflow. The table below carries the cumulative total
year by year; a packed while loop then counts the full years and the
final print adds the exact fraction of the next year (the builtin npv
knows no payback, so the recurrence is written out). Source: standard
capital-budgeting practice; see Brealey and Myers, Principles of
Corporate Finance, chapter 5.

Accuracy: the cumulative rows and the payback year are exact. The plain
payback ignores the time value of money; the discounted version is the
sibling script discounted-payback-period.epher.

The knobs to edit are in the knob section; everything after it is
machinery you can leave alone.
============================================================================ */

// ---- knobs ------------------------------------------------------------------
const invested = 100000     // the project's cost today
const yearly = {30000, 40000, 40000, 30000}   // inflows at the end of years 1 to 4

// ---- helpers ----------------------------------------------------------------
def cum(k) = if k == 1 then yearly[1] - invested else cum(k - 1) + yearly[k]  // cumulative cash flow through year k

// ---- results -----------------------------------------------------------------
// Cumulative cash flow through each year: still 70000 short after year 1,
// 30000 short after year 2, positive from year 3 on.
for k in 1 to 4 do {k, cum(k)}
// Count the full years: the loop state is {year, cumulative cash flow} and
// runs until the cumulative total turns positive.
v = {0, 0 - invested}
print("columns: year, cumulative cash flow")
while v[2] < 0 do v = {v[1] + 1, v[2] + yearly[v[1] + 1]}
// The payback is the last full year plus the fraction of the next year
// needed to cover the shortfall: 2 + 30000/40000 = 2.75 years.
print("payback period:", (v[1] - 1) + (yearly[v[1]] - v[2]) / yearly[v[1]], "years")
/* ---- expected output ----
= {{1, -70000}, {2, -30000}, {3, 10000}, {4, 40000}}
= {0, -100000}
= columns: year, cumulative cash flow
= payback period: 2.75 years
*/

/* ============================================================================
mortgage-rate.epher -- the interest rate a given payment implies, and the
difference between the quoted (APR) rate and the effective annual rate

The finance builtin tvm_i solves the annuity equation for the per-period
rate: given the term, principal (negative) and payment, it returns the
monthly rate r. Multiplying by 12 gives the nominal annual rate, the way
lenders quote an APR; compounding that monthly rate for a year gives the
higher effective annual rate (1+r)^12 - 1. Source: standard TVM
formulas; see Kellison, The Theory of Interest, chapters 2-3.

Accuracy: 12 displayed digits; tvm_i bisects the rate to about 1e-15.

The knobs to edit are in the knob section; everything after it is
machinery you can leave alone.
============================================================================ */

// ---- knobs ------------------------------------------------------------------
const principal = 200000    // loan amount at closing
const offered_payment = 1500 // monthly payment offered
const years = 30            // term in years

// ---- results -----------------------------------------------------------------
const r = tvm_i(years * 12, -principal, offered_payment, 0)   // monthly rate the payment implies (r, not i: i is reserved, guide 1.18)
print("monthly rate:", r)
print("nominal annual rate (APR, 12 x monthly):", 12 * r)
print("effective annual rate (1+r)^12 - 1:", (1 + r) ^ 12 - 1)
// The gap between 8.232% and 8.550% is monthly compounding: interest added
// every month earns interest itself. The quoted APR is the nominal 8.232%;
// the effective rate is what a year of that compounding truly costs.
/* ---- expected output ----
= monthly rate: 0.00685998148446
= nominal annual rate (APR, 12 x monthly): 0.0823197778135
= effective annual rate (1+r)^12 - 1: 0.0854978247676
*/

